def handle(app, svc):
    resp = svc.apply(app)
    result = resp["result"]
    outcome = result["outcome"]
    credit_limit = result.get("credit_limit", 0) or 0

    # Network referral rule: self_employed with requested_limit above 6000
    # must go to manual review instead of being issued; a decline stays a decline.
    if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 6000:
        if outcome == "approved":
            return {"action": "queue_review", "limit": 0}
        # declined / manual_review -> stays as below

    if outcome == "approved":
        return {"action": "issue", "limit": int(credit_limit)}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    if outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}
    # Fallback: unknown outcome -> manual review
    return {"action": "queue_review", "limit": 0}
